const { withPodfile } = require("@expo/config-plugins");

/**
 * Xcode 27 hard-errors on any target whose IPHONEOS_DEPLOYMENT_TARGET is below
 * 15.0. The app target is fine (15.1), but many pods — mostly resource/privacy
 * bundles like GoogleMobileAdsResources, *_Privacy, RNSVGFilters — declare 9.0
 * through 13.4 and fail the build.
 *
 * expo-build-properties' `ios.deploymentTarget` does NOT cover this: it rewrites
 * the app's Xcode project and the `platform :ios` line, but the Pods project is
 * generated by CocoaPods afterwards and keeps each pod's own value. Hence a
 * post_install hook. Lives in a plugin because ios/ is gitignored prebuild
 * output, so editing ios/Podfile by hand is lost on the next prebuild.
 */
const MIN_DEPLOYMENT_TARGET = "15.1";

const POD_FIX = `
    # Added by plugins/withIosPodDeploymentTarget.js — see that file for why.
    installer.generated_projects.each do |project|
      project.targets.each do |target|
        target.build_configurations.each do |config|
          current = config.build_settings['IPHONEOS_DEPLOYMENT_TARGET']
          if current.nil? || current.to_f < ${MIN_DEPLOYMENT_TARGET}
            config.build_settings['IPHONEOS_DEPLOYMENT_TARGET'] = '${MIN_DEPLOYMENT_TARGET}'
          end
        end
      end
    end
`;

module.exports = function withIosPodDeploymentTarget(config) {
  return withPodfile(config, (mod) => {
    let contents = mod.modResults.contents;

    if (contents.includes("withIosPodDeploymentTarget.js")) {
      return mod;
    }

    // Append inside the existing `post_install do |installer|` block, after the
    // react_native_post_install(...) call closes.
    const marker = /(post_install do \|installer\|[\s\S]*?\n    \)\n)/;
    if (marker.test(contents)) {
      contents = contents.replace(marker, (m) => `${m}${POD_FIX}`);
    } else {
      throw new Error(
        "withIosPodDeploymentTarget: could not find the post_install block in the Podfile",
      );
    }

    mod.modResults.contents = contents;
    return mod;
  });
};
